  [["Größe", "meist 15 bis 40 cm lang"], ["Wo zu finden", "Steine, Buhnen, Muschelbänke, Spülsaum"], ["Luftblasen", "halten die Pflanze im Wasser aufrecht zum Licht"]],
  [["Wie lebt der Blasentang?", "Er wächst fest an Steinen und Buhnen. Seine Luftblasen tragen ihn bei Flut nach oben ins Licht."],
   ["Lebensraum", "Zwischen den Ästen leben Schnecken, Krebse und junge Fische."],
   ["Gut zu wissen", "In der Ostsee war Blasentang früher viel häufiger. Er ist ein wichtiger Hinweis auf sauberes Wasser."]],
  "Tang auf Steinen wachsen lassen. Angespülten Tang am Strand liegen lassen, er ist Nahrung für viele Tiere.",
